-- 9047_s4_check_statement_merge_audit.sql -- second and third live AI runs on the test instance (2026-11-20/21; OD-LIVE-3,
-- "确认" 2026-11-21 06:27 America/Toronto; docs/s4/S4_9047_Implementation_Notes.md).
--   NEW bnx.cmd_check_statement (tier 1; PWA and MCP fin.draft.check_statement, scope finance.draft): F-LIVE-9. Runs
--       fin.draft.create_statement with the same arguments in a subtransaction that is rolled back, and returns the checks
--       only (stored: false). An unsure AI checks its reading instead of sending trial drafts.
--   MODIFY bnx.cmd_resolve_account_proposal (9045): F-SIN-2. The merge target (a UUID under the key merge_into, which has no
--       id token) went into the audit payload as free text, so the SIN guard refused about 0.1% of merges at random; it is
--       audited as merge_into_id. The request and its idempotency hash are unchanged. Changed lines are marked "-- 9047".
--   Catalog: tools/s4/catalog_build.py reads the keys of a command that another command runs with its whole input.
-- Expand-only. Catalog: the delta block below (generated by tools/s4/catalog_build.py).
set role bnx_definer;

-- ---------- MODIFY bnx.cmd_resolve_account_proposal (9045) ----------
create or replace function bnx.cmd_resolve_account_proposal(cred jsonb, cmd jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); rc jsonb; p record; t record; r jsonb := '{}'; act text := cmd->>'action';
        acid uuid; granted boolean := false;                                                                              -- 9045
begin
  perform bnx.require(a, 2);
  rc := bnx.idem_begin(a, 'resolve_account_proposal', cmd); if rc is not null then return rc; end if;
  select * into p from bnx_intake.account_proposal where id = (cmd->>'proposal_id')::uuid for update;
  if not found then perform bnx.fail('NOT_FOUND', 'P0404'); end if;
  if p.state <> 'PROPOSED' then perform bnx.fail('PROPOSAL_NOT_OPEN', 'P0409', p.state); end if;
  if act = 'approve' then
    r := bnx.cmd_create_account(cred, jsonb_strip_nulls(jsonb_build_object('idempotency_key', 'acct-proposal-' || p.id,
           'kind', coalesce(cmd->>'kind', p.suggested_kind), 'institution_id', coalesce(cmd->>'institution_id', p.institution_id::text),  -- 9045
           'label', coalesce(nullif(btrim(cmd->>'label'), ''), p.suggested_label),                                          -- 9045
           'currencies', to_jsonb(p.currencies), 'visibility', cmd->>'visibility', 'region_scope', cmd->>'region_scope',
           'masked_display', p.reference_display)));
    update bnx_intake.account_proposal set state = 'APPROVED', account_id = (r->>'account_id')::uuid, decided_by = a.member_id, decided_at = now()
     where id = p.id;
    acid := (r->'account_currencies'->0->>'account_currency_id')::uuid;                                                 -- 9045
    -- the first statement's opening balance becomes the opening anchor (the member may decline it)                    -- 9045
    if p.opening is not null and coalesce(cmd->>'set_opening', 'true') <> 'false' and acid is not null then            -- 9045
      perform bnx.cmd_set_opening(cred, jsonb_build_object('idempotency_key', 'acct-proposal-opening-' || p.id,      -- 9045
        'account_currency_id', acid, 'anchor_date', p.opening->>'anchor_date', 'amount', p.opening->>'amount',         -- 9045
        'reason', 'opening balance of the first statement', 'certainty', 'declared'));                                  -- 9045
    end if;                                                                                                              -- 9045
    -- the AI connection that proposed the account may see it (second step: it submits the statement); default yes     -- 9045
    if p.origin_connection_id is not null and coalesce(cmd->>'grant_connection', 'true') <> 'false' then                -- 9045
      update bnx.ai_connection set account_currency_ids = array(select distinct x from unnest(account_currency_ids || -- 9045
               array(select (e->>'account_currency_id')::uuid from jsonb_array_elements(r->'account_currencies') e)) x) -- 9045
       where id = p.origin_connection_id and revoked_at is null and member_id = a.member_id;                            -- 9045
      if found then                                                                                                     -- 9045
        granted := true;                                                                                                 -- 9045
        insert into bnx.ai_connection_subset(connection_id, kind, value)                                                -- 9045
        select p.origin_connection_id, 'account_currency', e->>'account_currency_id'                                    -- 9045
          from jsonb_array_elements(r->'account_currencies') e on conflict do nothing;                                  -- 9045
      end if;                                                                                                            -- 9045
    end if;                                                                                                              -- 9045
  elsif act = 'reject' then
    update bnx_intake.account_proposal set state = 'REJECTED', decided_by = a.member_id, decided_at = now() where id = p.id;
  elsif act = 'merge' then
    select * into t from bnx_intake.account_proposal where id = (cmd->>'merge_into')::uuid for update;
    if t.id is null or t.state <> 'PROPOSED' or t.id = p.id then perform bnx.fail('PROPOSAL_NOT_OPEN', 'P0409', 'merge target'); end if;
    update bnx_intake.account_proposal set signal_ids = array(select distinct unnest(t.signal_ids || p.signal_ids)),
           currencies = array(select distinct unnest(t.currencies || p.currencies) order by 1),
           holder_names = array(select distinct unnest(t.holder_names || p.holder_names) order by 1),
           rule_codes = array(select distinct unnest(t.rule_codes || p.rule_codes) order by 1),
           match_trace = t.match_trace || jsonb_build_object('merged_by_member', p.id) where id = t.id;
    update bnx_intake.account_proposal set state = 'MERGED', merged_into = t.id, decided_by = a.member_id, decided_at = now() where id = p.id;
  else perform bnx.fail('VALIDATION_FAILED', 'P0422', 'action');
  end if;
  -- 9047 (F-SIN-2): the merge target is a UUID under a key without an id token, so the SIN guard of bnx.audit read it as free
  -- text and refused about 0.1% of merges at random; it is audited as merge_into_id (the request itself is unchanged)
  perform bnx.audit(a, 'resolve_account_proposal', jsonb_build_object('proposal_id', p.id, 'action', act),
                    case when cmd ? 'merge_into' then (cmd - 'merge_into') || jsonb_build_object('merge_into_id', cmd->'merge_into')  -- 9047
                         else cmd end, null);                                                                                       -- 9047
  return bnx.idem_end(a, 'resolve_account_proposal', cmd, jsonb_build_object('proposal_id', p.id, 'action', act)
         || case when r ? 'account_id' then jsonb_build_object('account_id', r->>'account_id', 'account_currencies', r->'account_currencies',
                 'opening_set', p.opening is not null and coalesce(cmd->>'set_opening', 'true') <> 'false',              -- 9045
                 'connection_granted', granted) else '{}' end);                                                            -- 9045
end $$;

-- ---------- NEW bnx.cmd_check_statement ----------
-- F-LIVE-9: an AI host that is unsure of a reading (signs, the opening, a missed line) sent one-line trial drafts to learn
-- how the checks answer. This command runs exactly what fin.draft.create_statement runs, with the same arguments, inside a
-- subtransaction that is then rolled back: the answer is the checks' result, and nothing is stored (no draft, no audit entry,
-- no idempotency record; a superseded draft stays as it was).
create function bnx.cmd_check_statement(cred jsonb, cmd jsonb) returns jsonb
language plpgsql security definer set search_path = pg_catalog, pg_temp as $$
declare a bnx.actor := bnx.resolve_actor(cred); r jsonb;
begin
  perform bnx.require(a, 1);   -- the tier of fin.draft.create_statement, which checks the rest (channel, scope, accounts)
  begin
    -- a letters-only key, so the SIN guard of the (rolled back) audit never meets a digit run of ours
    r := bnx.cmd_draft_statement(cred, (cmd - 'idempotency_key')
           || jsonb_build_object('idempotency_key', 'check-' || translate(md5(random()::text || clock_timestamp()::text), '0123456789', 'ghijklmnop')));
    raise exception using errcode = 'P0999', message = 'BNX_CHECK_ONLY';
  exception when sqlstate 'P0999' then
    if sqlerrm <> 'BNX_CHECK_ONLY' then raise; end if;
  end;
  return jsonb_build_object('stored', false, 'kind', r->'kind', 'hold_reasons', r->'hold_reasons',
                            'validation_result', r->'validation_result', 'continuity', r->'continuity');
end $$;

insert into bnx.function_scope(function_name, scope, legacy_read, legacy_propose, needs_ac_subset, note)
values ('cmd_check_statement', 'finance.draft', false, false, true, 'fin.draft.check_statement');

select bnx.apply_grants();

